function rCode(){var s='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',r='';for(var i=0;i<4;i++)r+=s[Math.floor(Math.random()*s.length)];return r;}
function drawCaptcha(){captcha=rCode();var c=$('captcha'),x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.fillStyle='#eef2f7';x.fillRect(0,0,c.width,c.height);for(var i=0;i<3;i++){x.strokeStyle='#c9d4e0';x.beginPath();x.moveTo(Math.random()*c.width,Math.random()*c.height);x.lineTo(Math.random()*c.width,Math.random()*c.height);x.stroke();}x.font='bold 22px Arial';for(var i=0;i<captcha.length;i++){x.fillStyle=['#7B68EE','#e5484d','#ff9500','#6A5ACD'][i%4];x.save();x.translate(18+i*20,26);x.rotate((Math.random()-0.5)*0.4);x.fillText(captcha[i],0,0);x.restore();}}
function toggleReg(){isReg=!isReg;$('loginName').style.display=isReg?'block':'none';$('loginPass2').style.display=isReg?'block':'none';$('loginInvite').style.display=isReg?'block':'none';$('captchaRow').style.display=isReg?'block':'none';$('loginBtn').textContent=isReg?'注 册':'登 录';$('regToggle').textContent=isReg?'已有账号？登录':'没有账号？注册';$('loginErr').textContent='';if(isReg)drawCaptcha();}
function fakeEmail(qq){return 'qq'+qq.trim()+'@qq.local';}
async function doLogin(){var qq=$('loginQQ').value.trim(),pass=$('loginPass').value,err=$('loginErr');if(!/^\d{5,12}$/.test(qq)){err.textContent='请输入正确的QQ号';return;}if(pass.length<6){err.textContent='密码至少6位';return;}var email=fakeEmail(qq);try{if(isReg){var name=$('loginName').value.trim(),p2=$('loginPass2').value,inv=$('loginInvite').value.trim();if(name.length<2||name.length>12){err.textContent='用户名2~12个字';return;}if(pass!==p2){err.textContent='两次密码不一致';return;}if(!captcha||$('loginCaptcha').value.trim().toUpperCase()!==captcha){err.textContent='验证码错误';drawCaptcha();return;}var r=await api('/auth/v1/signup',{method:'POST',body:JSON.stringify({email:email,password:pass,data:{nickname:name,qq:qq}})});if(r&&r.access_token){localStorage.setItem('sb_token',r.access_token);localStorage.setItem('sb_refresh',r.refresh_token);localStorage.setItem('sb_user',JSON.stringify(r.user));await afterLogin(r.user);if(inv)dbR('apply_invite',{p_invite_code:inv.toUpperCase()}).then(function(x){if(x==='OK')toast('🎉邀请成功+25硬币');}).catch(function(){});}else{err.textContent='注册失败：该QQ号可能已注册';}}else{var r2=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:email,password:pass})});if(r2&&r2.access_token){localStorage.setItem('sb_token',r2.access_token);localStorage.setItem('sb_refresh',r2.refresh_token);localStorage.setItem('sb_user',JSON.stringify(r2.user));afterLogin(r2.user);}else{err.textContent='登录失败：QQ号或密码错误，未注册请先注册';}}}catch(e){err.textContent='操作失败：'+e.message;}}
async function afterLogin(u){try{var b=await dbR('is_device_banned',{dev:did()});if(b){logout();toast('🚫该设备已被封禁');return;}await dbU('profiles','id=eq.'+u.id,{device_id:did()});}catch(e){}showMain();}
function logout(){localStorage.removeItem('sb_token');localStorage.removeItem('sb_refresh');localStorage.removeItem('sb_user');location.reload();}
