function resetAfk(){if(afkT)clearTimeout(afkT);afkT=setTimeout(function(){showAfk();},7200000);}
function showAfk(){$('afkOverlay').classList.add('show');drawAfkCaptcha();}
function drawAfkCaptcha(){afkC=rCode();var c=$('afkCaptcha'),x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.fillStyle='#eef2f7';x.fillRect(0,0,c.width,c.height);for(var i=0;i<4;i++){x.strokeStyle='#c9d4e0';x.beginPath();x.moveTo(Math.random()*c.width,Math.random()*c.height);x.lineTo(Math.random()*c.width,Math.random()*c.height);x.stroke();}x.font='bold 24px Arial';for(var i=0;i<afkC.length;i++){x.fillStyle=['#7B68EE','#e5484d','#ff9500','#6A5ACD'][i%4];x.save();x.translate(24+i*24,28);x.rotate((Math.random()-0.5)*0.4);x.fillText(afkC[i],0,0);x.restore();}}
function checkAfk(){if($('afkInput').value.trim().toUpperCase()===afkC){$('afkOverlay').classList.remove('show');$('afkInput').value='';resetAfk();}else{toast('验证码错误');drawAfkCaptcha();}}
